import * as THREE from 'three';

// ---------------------------------------------------------------------------
// 7-segment layout
//
//        A
//      -----
//     |     |
//   F |     | B
//      -----
//     |     |
//   E |     | C
//      -----  . G (decimal point, unused here)
//        D
//
// Segments are axis-aligned boxes in the XY plane, centered on the origin.
// ---------------------------------------------------------------------------

const SEGMENT_LENGTH = 1.0; // long dimension of a horizontal/vertical bar
const SEGMENT_THICKNESS = 0.18; // short dimension of every bar
const SEGMENT_DEPTH = 0.12; // z depth of every box

export const SEGMENTS = {
  A: { x: 0, y: SEGMENT_LENGTH / 2, w: SEGMENT_LENGTH, h: SEGMENT_THICKNESS },
  B: { x: SEGMENT_LENGTH / 2, y: 0, w: SEGMENT_THICKNESS, h: SEGMENT_LENGTH },
  C: { x: SEGMENT_LENGTH / 2, y: -SEGMENT_LENGTH / 2, w: SEGMENT_THICKNESS, h: SEGMENT_LENGTH },
  D: { x: 0, y: -SEGMENT_LENGTH / 2, w: SEGMENT_LENGTH, h: SEGMENT_THICKNESS },
  E: { x: -SEGMENT_LENGTH / 2, y: 0, w: SEGMENT_THICKNESS, h: SEGMENT_LENGTH },
  F: { x: -SEGMENT_LENGTH / 2, y: SEGMENT_LENGTH / 2, w: SEGMENT_THICKNESS, h: SEGMENT_LENGTH },
  G: { x: 0, y: 0, w: SEGMENT_LENGTH, h: SEGMENT_THICKNESS },
};

// Lit segments per character. G is the middle bar.
export const GLYPHS = {
  '0': ['A', 'B', 'C', 'D', 'E', 'F'],
  '1': ['B', 'C'],
  '2': ['A', 'B', 'D', 'E', 'G'],
  '3': ['A', 'B', 'C', 'D', 'G'],
  '4': ['B', 'C', 'F', 'G'],
  '5': ['A', 'C', 'D', 'F', 'G'],
  '6': ['A', 'C', 'D', 'E', 'F', 'G'],
  '7': ['A', 'B', 'C'],
  '8': ['A', 'B', 'C', 'D', 'E', 'F', 'G'],
  '9': ['A', 'B', 'C', 'D', 'F', 'G'],
  A: ['A', 'B', 'C', 'E', 'F', 'G'],
  E: ['A', 'D', 'E', 'F', 'G'],
  F: ['A', 'E', 'F', 'G'],
  H: ['B', 'C', 'E', 'F', 'G'],
  L: ['D', 'E', 'F'],
  O: ['A', 'B', 'C', 'D', 'E', 'F'], // same shape as 0
  P: ['A', 'B', 'E', 'F', 'G'],
};

const segmentGeometry = new THREE.BoxGeometry(1, 1, SEGMENT_DEPTH);

/**
 * Number of lit segments used by a character.
 * @param {string} ch single character
 * @returns {number}
 */
export function segmentCount(ch) {
  const glyph = GLYPHS[ch];
  if (!glyph) {
    throw new Error(
      `Unsupported character ${JSON.stringify(ch)}: marquee supports only ${Object.keys(GLYPHS).join(' ')}`
    );
  }
  return glyph.length;
}

/**
 * Build a Group of box meshes for the lit segments of one character.
 * @param {string} ch single supported character
 * @returns {THREE.Group} group whose children are the lit segment meshes
 */
export function buildGlyph(ch) {
  const lit = GLYPHS[ch];
  if (!lit) {
    throw new Error(
      `Unsupported character ${JSON.stringify(ch)}: marquee supports only ${Object.keys(GLYPHS).join(' ')}`
    );
  }
  const material = new THREE.MeshStandardMaterial({ color: 0xff3b30 }); // "lit" red
  const group = new THREE.Group();
  for (const seg of lit) {
    const { x, y, w, h } = SEGMENTS[seg];
    const mesh = new THREE.Mesh(segmentGeometry, material);
    mesh.position.set(x, y, 0);
    mesh.scale.set(w, h, 1);
    mesh.userData.segment = seg;
    group.add(mesh);
  }
  return group;
}

/**
 * Lay out glyphs left to right with a fixed advance between them.
 * @param {string} text text using only supported characters
 * @param {number} spacing distance between consecutive glyph origins
 * @returns {THREE.Group} group of glyph groups
 */
export function buildMarquee(text, spacing = 1.4) {
  const root = new THREE.Group();
  for (let i = 0; i < text.length; i++) {
    const glyph = buildGlyph(text[i]);
    glyph.position.x = i * spacing;
    root.add(glyph);
  }
  return root;
}

