import { describe, it, expect } from 'vitest';
import { buildGlyph, buildMarquee, segmentCount } from '../src/marquee.js';

describe('segmentCount', () => {
  it('digits use the classic 7-segment counts', () => {
    expect(segmentCount('8')).toBe(7);
    expect(segmentCount('1')).toBe(2);
    expect(segmentCount('0')).toBe(6);
    expect(segmentCount('4')).toBe(4);
  });

  it('letters are supported too', () => {
    for (const ch of ['A', 'E', 'F', 'H', 'L', 'O', 'P']) {
      expect(() => segmentCount(ch)).not.toThrow();
    }
    expect(segmentCount('H')).toBe(5);
  });

  it('throws on unsupported characters with a helpful message', () => {
    expect(() => segmentCount('?')).toThrow(/Unsupported character "\?"/);
    expect(() => buildGlyph('z')).toThrow(/marquee supports only/);
  });
});

describe('buildMarquee', () => {
  it('lays out HELLO as five glyphs', () => {
    const marquee = buildMarquee('HELLO', 1.2);
    expect(marquee.children.length).toBe(5);
  });

  it('consecutive glyph x offsets differ by exactly the spacing', () => {
    const marquee = buildMarquee('HELLO', 1.2);
    for (let i = 1; i < marquee.children.length; i++) {
      const dx =
        marquee.children[i].position.x - marquee.children[i - 1].position.x;
      expect(dx).toBeCloseTo(1.2, 10);
    }
  });

  it('"01" has exactly segmentCount("0") + segmentCount("1") meshes', () => {
    const marquee = buildMarquee('01', 1.2);
    let meshes = 0;
    marquee.traverse((obj) => {
      if (obj.isMesh) meshes++;
    });
    expect(meshes).toBe(6 + 2);
  });
});

